#include "stdafx.h"#include "Client.h"KClient::KClient( LPSTR _ObjName ) :	IBaseModel ( _ObjName ){  TypeObj = RSU_Obj;}int KClient::Init( int ){  return KRsuSharedClient::InitializeServer( "SOEtransport_Server", ObjName );}int KClient::Step0(){  return KRsuSharedClient::StepAfterInit();}int KClient::Step1(){  return KRsuSharedClient::StepAfterRestored();}int KClient::StepT(double dt){  double dtMs = dt * 3600. * 1000;  return KRsuSharedClient::CalcStep( (int)dtMs );}